            count = count + 1
        }
    }
    count
}

fn max_reading(v: Vec<Int>) -> Option<Int> {
    let mut max = None
    for x in v {
        max = match max {
            Some(m) => {
                if x > m {
                    Some(x)
                } else {
                    Some(m)
                }
            },
            None => Some(x),
        }
    }
    max
}

